// ============================================================
//  Seeder
// ============================================================
const seedProducts = async () => {
  try {
    console.log('\n🔌 Connecting to MongoDB...');
    await mongoose.connect(process.env.DATABASE);
    console.log('✅ MongoDB connected\n');

    console.log('🗑️  Clearing existing products...');
    await Product.deleteMany({});
    console.log('✅ Old products cleared\n');

    let totalSeeded = 0;
    const categories = Object.keys(productData);

    for (const category of categories) {
      const items = productData[category];
      console.log(`\n📦 Seeding category: "${category}" (${items.length} products)`);

      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        const discountPct = Math.round(
          ((item.originalPrice - item.price) / item.originalPrice) * 100
        );

        await Product.create({
          name:          item.name,
          description:   item.description,
          category:      category,
          price:         item.price,
          originalPrice: item.originalPrice,
          discount:      discountPct,
          rating:        item.rating,
          reviewCount:   item.reviewCount,
          sizes:         item.sizes,
          colors:        item.colors,
          isInStock:     true,
          images:        item.images,
          public_ids:    [],   // direct URLs — no Cloudinary public_id needed
        });

        process.stdout.write(`  ✅ [${i + 1}/${items.length}] ${item.name}\n`);
        totalSeeded++;
      }
    }

    const finalCount = await Product.countDocuments();

    console.log('\n╔══════════════════════════════════════╗');
    console.log('║       🌱 PRODUCT SEED COMPLETE!      ║');
    console.log('╠══════════════════════════════════════╣');
    console.log(`║  Categories:  ${String(categories.length).padEnd(22)} ║`);
    console.log(`║  Products:    ${String(finalCount).padEnd(22)} ║`);
    console.log('╚══════════════════════════════════════╝\n');

    process.exit(0);
  } catch (error) {
    console.error('\n❌ Seeding failed:', error.message);
    process.exit(1);
  }
};

seedProducts();
